    const pending: PendingRefund = {
      order: order.order,
      skus,
      amount,
      idempotencyKey: `refund:${order.order}:${priorRefunds}:${[...skus].sort().join(",")}`,
      expiresAt: this.d.now().getTime() + this.d.confirmTimeoutMs,
